#!/usr/bin/env python3
from stepup.core.api import run, static
from stepup.report.api import compile_typst

static("../doc/main.typ", "../doc/other.typ")
compile_typst("../doc/main.typ", step_info="../current_step_info.json")
run(
    "echo 'This sentence is generated by another step.' > generated.typ",
    out="generated.typ",
    workdir="../doc",
    shell=True,
    optional=True,
)
